import { task, launchBrowser, writeResult, clip, SCREENSHOT_PATH } from "/opt/teger/scout-kit.mjs";

(async () => {
  const browser = await launchBrowser();
  const page = await browser.newPage();

  // Navigation
  const nav = await page.goto(task.url, { timeout: task.limits.navigationTimeoutMs });
  const { navigationError, loadEventFired, finalUrl, status } = nav;
  const httpStatus = status ?? null;
  const requestedUrl = task.url;

  // Wait for ready state and some visible content (max 5s)
  await page.waitFor(() => document.readyState === "complete" && document.body.innerText.length > 0, {
    timeoutMs: 5000,
    intervalMs: 100,
  }).catch(() => {}); // timeout is okay; we continue with what we have

  const extractionErrors = [];
  let title = null;
  let claimedIdentity = { siteName: null, brandMentions: [], evidence: [] };
  let forms = [];
  let loginFormDetected = false;
  let textSignals = { urgencyPhrases: [], credentialRequests: [], instructionsToAI: [] };
  let visibleTextSample = "";
  let externalScriptOrigins = [];
  let blockedRequests = [];
  let contactedHosts = [];
  let screenshot = { path: SCREENSHOT_PATH, bytes: 0 };
  let screenshotError = null;
  let notes = [];

  try {
    // Title
    title = await page.evaluate(() => document.title.trim() || null);

    // Claimed identity
    const identityInfo = await page.evaluate(() => {
      const ogSite = document.querySelector('meta[property="og:site_name"]')?.content?.trim() || null;
      const appName = document.querySelector('meta[name="application-name"]')?.content?.trim() || null;
      const logoAlt = Array.from(document.querySelectorAll('img[alt]'))
        .find(i => i.offsetWidth > 40 && i.offsetHeight > 40 && i.alt.trim().length > 0)?.alt.trim() || null;
      const siteName = ogSite || appName || logoAlt || null;

      // brand mentions from headings, logo alt, title
      const heads = Array.from(document.querySelectorAll('h1,h2,h3,h4,h5,h6'))
        .map(e => e.textContent.trim())
        .filter(Boolean);
      const logoAlts = Array.from(document.querySelectorAll('img[alt]'))
        .map(i => i.alt.trim())
        .filter(Boolean);
      const titleTxt = document.title.trim();
      const all = [...new Set([...heads, ...logoAlts, titleTxt])]
        .filter(s => s.length > 1 && s.length < 50)
        .slice(0, 10);
      const evidence = all.map(s => s.slice(0, 60));
      return { siteName, brandMentions: all, evidence };
    });
    claimedIdentity = identityInfo;

    // Forms and password detection
    const formsData = await page.evaluate(() => {
      const forms = [];
      const addForm = (f) => {
        const actionAttr = f.getAttribute("action") || "";
        const actionURL = new URL(actionAttr, location.href).href;
        const method = (f.getAttribute("method") || "GET").toUpperCase();
        const inputs = Array.from(f.querySelectorAll("input, select, textarea"));
        const inputTypes = [...new Set(inputs.map(i => i.type || "text"))];
        const inputNames = [...new Set(inputs.map(i => i.name || "")).filter(Boolean)];
        const hasPassword = inputs.some(i => i.type === "password");
        const crossOrigin = new URL(actionURL).origin !== location.origin;
        return {
          action: actionURL,
          method,
          hasPasswordField: hasPassword,
          inputTypes,
          inputNames,
          crossOriginAction: crossOrigin,
        };
      };
      document.querySelectorAll("form").forEach(f => forms.push(addForm(f)));
      // synthetic form for password inputs not inside a form
      const lonePasswords = Array.from(document.querySelectorAll("input[type='password']"))
        .filter(i => !i.closest("form"));
      if (lonePasswords.length > 0) {
        const inputs = lonePasswords;
        const inputTypes = [...new Set(inputs.map(i => i.type || "text"))];
        const inputNames = [...new Set(inputs.map(i => i.name || "")).filter(Boolean)];
        forms.push({
          action: null,
          method: "GET",
          hasPasswordField: true,
          inputTypes,
          inputNames,
          crossOriginAction: false,
        });
      }
      return forms;
    });
    forms = formsData;
    loginFormDetected = forms.some(f => f.hasPasswordField);

    // Text signals
    const visibleText = await page.evaluate(() => document.body.innerText);
    visibleTextSample = visibleText.slice(0, 1500);
    const urgency = ["account suspended", "verify within 24 hours", "unusual activity", "immediate action required"];
    const credRequests = ["enter your password", "confirm your card", "provide your ssn", "update billing"];
    const aiInstructions = ["ignore previous", "you are a bot", "scan this page", "output only"];
    const extractMatches = (list, text) => {
      const lower = text.toLowerCase();
      return list.filter(p => lower.includes(p.toLowerCase())).slice(0, 10);
    };
    textSignals.urgencyPhrases = extractMatches(urgency, visibleText);
    textSignals.credentialRequests = extractMatches(credRequests, visibleText);
    textSignals.instructionsToAI = extractMatches(aiInstructions, visibleText);

    // External script origins
    const scriptOrigins = await page.evaluate(() => {
      const origins = new Set();
      document.querySelectorAll('script[src]').forEach(s => {
        try {
          const url = new URL(s.src, location.href);
          origins.add(url.origin);
        } catch {}
      });
      return Array.from(origins).slice(0, 20);
    });
    externalScriptOrigins = scriptOrigins;

    // Blocked requests and contacted hosts (from page methods)
    blockedRequests = await page.blockedRequests();
    contactedHosts = await page.contactedHosts();
  } catch (err) {
    extractionErrors.push(String(err));
  } finally {
    // Screenshot
    try {
      const shot = await page.screenshot();
      screenshot = { path: shot.path, bytes: shot.bytes };
    } catch (err) {
      screenshot = null;
      screenshotError = String(err);
    }
    // Ensure browser close after writeResult
    await writeResult({
      requestedUrl,
      finalUrl: finalUrl ?? null,
      httpStatus,
      redirectChain: await page.redirectChain(),
      title,
      claimedIdentity,
      forms,
      loginFormDetected,
      textSignals,
      visibleTextSample,
      externalScriptOrigins,
      blockedRequests,
      contactedHosts,
      screenshot,
      screenshotError,
      extractionErrors,
      notes: [],
    });
    await browser.close();
  }
})();
